import hashlib, json  # Produce source-bound statistical charts without creating or interpolating any spatial FEM contour.
from pathlib import Path  # Read only explicit full-field exports already validated by the report gate.
def sha(path):  # Verify actual input bytes again immediately before numerical chart reduction.
    with Path(path).open('rb') as stream: return hashlib.file_digest(stream, 'sha256').hexdigest()  # Never rely on a remembered filename alone.
def require(condition, message):  # A missing field or changed archive blocks chart generation.
    if not condition: raise RuntimeError(message)  # No fake data or zero-filled fallback is permitted.
def temporal_group(arrays, norm, group):  # Compute complete unknown-field per-frame relative error on the original discrete entities.
    import numpy as np  # Use the same actual array arithmetic library without importing or executing the trainer.
    columns = [i for i, value in enumerate(norm['field_groups']) if value == group]; prediction = arrays['prediction'][1:][:, :, columns]; reference = arrays['reference'][1:][:, :, columns]  # Explicit chained indexing excludes only the initial frame and preserves original frame/entity/component axes.
    support = np.broadcast_to(arrays['state_mask'][:, columns].astype(bool), prediction.shape); prescribed = arrays['prescribed_mask'][1:][:, :, columns].astype(bool); mask = support & ~prescribed  # Preserve every unknown native field entry while excluding prescribed values.
    weights = np.asarray([2. if group in ('cauchy_stress', 'plastic_metric', 'backstress') and any(axis in norm['fields'][j].lower() for axis in ('xy', 'xz', 'yz')) else 1. for j in columns]); weighted = mask * weights[None, None, :]  # Match Frobenius tensor weighting without mixing physical units.
    numerator = np.sqrt(np.sum((prediction - reference) ** 2 * weighted, axis=(1, 2))); centered = reference - np.asarray(norm['state_offset'])[columns][None, None, :]  # Use original training offsets, never prediction-dependent denominators.
    magnitude = np.sqrt(np.sum(centered ** 2 * weighted, axis=(1, 2))); floor = norm['floor_fraction'] * norm['group_scales'][group] * np.sqrt(np.sum(weighted, axis=(1, 2))); denominator = np.maximum(np.maximum(magnitude, floor), 1e-12)  # Use the fixed training scale separately at every actual original frame.
    return (numerator / denominator).tolist()  # This is a time-series statistical error, not a reconstructed spatial stress field.
def create(summary, paths, directory):  # Generate charts only after the final reporter has verified closed release-bound results.
    require(summary['status'] == 'V2_TWO_FAMILY_EVIDENCE_CLOSED_SCIENTIFIC_GATES_SEPARATE', 'Charts require a verified closed two-family report')  # A partially assembled live experiment cannot be plotted as a completed result.
    import matplotlib  # Use a standard scientific plotting implementation rather than synthetic chart imagery.
    matplotlib.use('Agg')  # Render standalone artifacts without opening an interactive GUI.
    import matplotlib.pyplot as plt  # Produce exportable PNG charts with native Matplotlib axes and legends.
    import numpy as np  # Load complete verified exported arrays and perform explicitly scoped reductions.
    directory = Path(directory); directory.mkdir(parents=True, exist_ok=True); references = {row['path']: row for row in summary['sources']}; figures = []; strategy_names = ('initial', 'active', 'random'); colors = ('#6b7c93', '#136e90', '#b87623')  # Use consistent model colors across tables, errors and costs.
    def checked(path):  # Refuse a file absent from the already completed report evidence manifest.
        path = str(Path(path).resolve()); require(path in references and sha(path) == references[path]['sha256'], f'Chart input is unverified or changed: {path}'); return path  # Source identity is checked immediately before use.
    def save(fig, name, caption, source_paths, data):  # Save exact plotting values and source references alongside every image.
        image = directory / (name + '.png'); fig.savefig(image, dpi=165, bbox_inches='tight', facecolor='white'); plt.close(fig); record = {'kind': 'STATISTICAL_ERROR_OR_COST_CHART_NOT_FEM_SPATIAL_FIELD', 'image': str(image), 'image_sha256': sha(image), 'caption_cn': caption, 'sources': [references[str(Path(p).resolve())] for p in source_paths], 'data': data, 'plot_source_sha256': sha(__file__)}  # Make chart values independently inspectable without reverse-reading pixels.
        receipt = directory / (name + '.json'); receipt.write_text(json.dumps(record, ensure_ascii=False, indent=2, allow_nan=False) + '\n'); figures.append({key: record[key] for key in ('kind', 'image', 'image_sha256', 'caption_cn')} | {'receipt': {'path': str(receipt), 'sha256': sha(receipt)}})  # Store the exact figure receipt and byte identities for report embedding.
    config_path = checked(paths['controller_config']); config = json.loads(Path(config_path).read_text()); public_path = checked(config['design_contract']['path']); public = json.loads(Path(public_path).read_text())  # Normalization and original references remain the release-bound initial-training values.
    for family in ('friction', 'rebar'):  # Keep field groups and timing strata of the two physical families separate.
        for split in ('test', 'ood'):  # Separate ordinary interpolation and OOD accuracy instead of pooling them.
            groups = summary['families'][family]['strategies']['initial'][split]['groups']; labels = [row['group'] for row in groups]; fig, ax = plt.subplots(figsize=(12, 5)); x = np.arange(len(labels)); plotted = {}  # Establish one common group axis for the paired strategies.
            for offset, strategy in enumerate(strategy_names):  # Every frozen strategy appears even if it performs poorly.
                rows = {row['group']: row for row in summary['families'][family]['strategies'][strategy][split]['groups']}; values = [rows[name]['mean_relative_L2'] for name in labels]; plotted[strategy] = values; ax.bar(x + (offset - 1) * .25, [100 * v if v is not None else np.nan for v in values], .25, label=strategy, color=colors[offset])  # A missing qualified result remains a missing bar rather than zero.
            ax.set_xticks(x, [name.replace('_', '\n') for name in labels], fontsize=9); ax.set_ylabel('Full-field relative L2 (%)'); ax.set_title(f'{family} / {split}: physical-group errors'); ax.legend(); ax.grid(axis='y', alpha=.2); ax.set_axisbelow(True); fig.tight_layout()  # Label these as statistical full-field errors, not FE spatial clouds.
            source = str(Path(config['output_directory']) / family / 'final_test/summary.json'); save(fig, f'{family}_{split}_group_error', f'{family}／{split}：同一批新工况的完整未知场物理组误差均值；缺失参考不画为零。统计图，不是有限元空间场。', [source], {'groups': labels, 'relative_L2': plotted})  # Bind every displayed bar to its verified actual final summary.
    costs = summary['work']['acquisition_costs']; fig, axes = plt.subplots(1, 2, figsize=(12, 4.5)); labels = [f"{r['family']}\n{r['strategy']}" for r in costs]; x = np.arange(len(costs))  # Compare actual costs and admitted histories without conflating their denominators.
    axes[0].bar(x - .2, [r['charged_cold_seconds'] for r in costs], .2, label='charged cold', color='#136e90'); axes[0].bar(x, [r['actual_fresh_native_seconds'] for r in costs], .2, label='actual new native', color='#b87623'); axes[0].bar(x + .2, [r['budget_seconds'] for r in costs], .2, label='frozen budget', color='#aebdcc')  # Cached canonical charges remain distinct from actual newly executed solver time.
    axes[1].bar(x - .15, [r['qualified_histories'] for r in costs], .3, label='qualified histories', color='#136e90'); axes[1].bar(x + .15, [r['failed_reference_requests'] for r in costs], .3, label='failed reference requests', color='#b87623')  # Native failures are not labelled as NN–FEM negatives.
    for ax in axes: ax.set_xticks(x, labels, fontsize=8); ax.legend(fontsize=8); ax.grid(axis='y', alpha=.2); ax.set_axisbelow(True)  # Keep the two observed metrics visibly separated.
    axes[0].set_ylabel('Seconds; family-specific timing scopes'); axes[1].set_ylabel('Actual history/request count'); fig.tight_layout(); cost_sources = [str(Path(config['output_directory']) / r['family'] / r['strategy'] / 'native_budget.json') for r in costs]; save(fig, 'native_cost_and_histories', '实际冷算计费、实际新增原生执行与冻结预算分列；两家族计时口径不同，不合并拟合。合格历史和原生失败请求分开。', cost_sources, costs)  # Exact ledger sources accompany this budget/benefit view.
    for family in ('friction', 'rebar'):  # Plot deterministic representative histories without selecting cases by good-looking error.
        norm = public['families'][family]['normalization']; initial = summary['families'][family]['strategies']['initial']['case_results']  # Select IDs using registration identity and trustworthy reference availability only.
        for split in ('test', 'ood'):  # Retain one predeclared deterministic example from each input regime.
            eligible = sorted(row['id'] for row in initial if row['split'] == split and row['status'] == 'EVALUATED_FROZEN_RAW_EMISSION')  # Lexicographically first qualified ID is independent of observed error magnitude.
            if not eligible: continue  # No qualified FEM reference means no valid NN–FEM curve to plot.
            identity = eligible[0]; fig, axes = plt.subplots(1, 2, figsize=(12, 4.3)); source_paths = [public_path]; data = {}  # Preserve the representative-case selection rule in its actual receipt.
            for index, strategy in enumerate(strategy_names):  # Show all three fixed functions on the same exact native history.
                path = checked(Path(config['output_directory']) / family / 'final_test' / strategy / (identity + '.npz')); source_paths.append(path)  # A future or mismatched field archive cannot pass this identity check.
                with np.load(path, allow_pickle=False) as archive: arrays = {name: archive[name] for name in ('prediction', 'reference', 'state_mask', 'prescribed_mask')}  # Use complete original arrays, not reduced responses or summary-based fabricated fields.
                data[strategy] = {}  # Save every actual frame error used in the time-series chart.
                for axis, group in zip(axes, ('displacement', 'cauchy_stress')):  # Keep separate units and physical-group meanings on distinct axes.
                    values = temporal_group(arrays, norm, group); data[strategy][group] = values; axis.plot(range(1, len(values) + 1), np.asarray(values) * 100, color=colors[index], label=strategy); axis.set_title(group); axis.set_xlabel('Original noninitial frame index'); axis.set_ylabel('Per-frame full-field relative L2 (%)'); axis.grid(alpha=.2)  # Original frame number is not mislabelled as physical time for quasistatic histories.
            for axis in axes: axis.legend(fontsize=8)  # Preserve all comparison strategies in each physical group.
            fig.suptitle(f'{family} / {split} / {identity}'); fig.tight_layout(); save(fig, f'{family}_{split}_frame_errors', '同一工况的原始逐帧位移／应力完整未知场误差。按 ID 字典序选本划分第一条合格历史，未按误差挑选；横轴是原始帧索引，不冒称物理时间。', source_paths, {'selected_case': identity, 'selection_rule': 'lexicographically_first_qualified_registered_id', 'group_relative_L2_by_frame': data})  # Every curve remains a statistical comparison, never a spatial FEM stress cloud.
    return figures  # Return real chart artifacts with exact receipts for standalone HTML embedding.
